schema_example:
{
  "name": "create_invoice",
  "description": "Create invoice for a customer",
  "contract_version": "1.0",
  "parameters": {
    "type": "object",
    "properties": {
      "customer_id": { "type": "string", "description": "Unique customer id" },
      "amount": { "type": "number", "minimum": 0 },
      "currency": { "type": "string", "enum": ["USD","EUR","GBP"] },
      "metadata": { "type": "object", "additionalProperties": { "type": "string" } }
    },
    "required": ["customer_id","amount","currency"],
    "x-redwood-coerce": "coerce-with-hints",
    "x-redwood-paramOrder": ["customer_id","amount","currency","metadata"],
    "x-redwood-strict-additional": true
  }
}
